import java.io.*
import java.util.*

fun main() {
    val MOD = 1_000_000_007L
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val n = st.nextToken().toInt()
    val x = st.nextToken().toInt()
    val pos = st.nextToken().toInt()

    var left = 0
    var right = n
    var cntLess = 0
    var cntGreater = 0
    while (left < right) {
        val mid = (left + right) / 2
        if (mid == pos) {
            left = mid + 1
        } else if (mid < pos) {
            cntLess++
            left = mid + 1
        } else {
            cntGreater++
            right = mid
        }
    }

    val availLess = x - 1
    val availGreater = n - x

    if (cntLess > availLess || cntGreater > availGreater) {
        println(0)
        return
    }

    var ans = 1L
    for (i in 0 until cntLess) {
        ans = ans * ((availLess - i).toLong() % MOD) % MOD
    }
    for (i in 0 until cntGreater) {
        ans = ans * ((availGreater - i).toLong() % MOD) % MOD
    }
    val rem = n - 1 - cntLess - cntGreater
    for (i in 1..rem) {
        ans = ans * i.toLong() % MOD
    }
    println(ans)
}
